  //@ encoder_facts(self);
  //@ heap_facts(instance);
  Object *size = Instance_at(instance, Instance_LIST_SIZE_INDEX);
  if (!is_smi(size) || to > Smi_value__Objectp(size)) {
    return false;
  }
  Object *backing = Instance_at(instance, Instance_LIST_ARRAY_INDEX);
  if (is_smi(backing)) {
    return false;
  }
  //@ good_mem(objs, backing);
  Smi *class_id = HeapObject_class_id(HeapObject_cast__Objectp(backing));
  //@ heap_facts(backing);
  //@ open encoder(self, ids);
